## Dalitz 图性质探索


def cal_dis2line(params_line: list[float], coord_point: tuple[float]) -> float:
    """计算点 :math:`(x_0,y_0)` 到直线 :math:`Ax + By + C = 0` 的距离 

    .. math::

        d = \\frac{|Ax_0 + By_0 + C|}{\sqrt{A^2 + B^2}}

    Args:
        params_line (list[float]): 直线方程的参数 `[A, B, C]`
        coord_point (tuple[float]): 直线外点的坐标 :math:`(x_0, y_0)`

    Returns:
        float: 距离 `d`
    """
    A, B, C = params_line
    x0, y0 = coord_point
    d = np.abs(A * x0 + B * y0 + C) / np.sqrt(A**2 + B**2)
    return d


def cal_footpoint(params_line: list[float],
                  coord_point: tuple[float]) -> tuple[float]:
    """计算直线 :math:`Ax + By + C = 0` 与直线外一点 :math:`(x_0,y_0)` 的垂足

    由垂足属于直线且与直线外点构成的矢量垂直于直线可得垂足坐标为

    .. math::

        x_f &= \\frac{B^2 x_0 - A B y_0 - AC}{A^2 + B^2}

        y_f &= \\frac{-AB x_0 + A^2 y_0 - BC}{A^2 + B^2}

    Args:
        params_line (list[float]): 直线方程的参数 `[A, B, C]`
        coord_point (tuple[float]): 直线外点的坐标 :math:`(x_0, y_0)`

    Returns:
        tuple[float]: 垂足的坐标 :math:`(x_f , y_f)`
    """
    A, B, C = params_line
    x0, y0 = coord_point
    x_f = (B**2 * x0 - A * B * y0 - A * C) / (A**2 + B**2)
    y_f = (-A * B * x0 + A**2 * y0 - B * C) / (A**2 + B**2)
    coord_foot_point = (x_f, y_f)
    return coord_foot_point


def display_point_in_equilateral_triangle(times: int = 5) -> None:
    """显示等边三角形内部的一个随机点 :math:`(x_0, y_0)` 及其到三条边的距离

    Args:
        times (int, optional): 随机取点的次数. Defaults to 5.

    Example:
        >>> display_point_in_equilateral_triangle()

        .. image:: ../../src/img/display_point_in_equilateral_triangle.png
            :width: 400px
            :align: center
    """
    counter = 0
    while (counter < times):
        x0 = (np.random.rand() - 0.5) * 2 * h / np.sqrt(3)
        y0 = np.random.rand()

        # 根据随机点与左右边的关系判断点是否在等边三角形内部
        if (np.sqrt(3) * x0 + y0 - h <= 0) and (np.sqrt(3) * x0 - y0 + h >= 0):
            # print(x0, y0)
            inner_point = (x0, y0)

            # 等边三角形三条边的方程的参数
            edges_params = [[0, 1, 0], [np.sqrt(3), 1, -h],
                            [np.sqrt(3), -1, h]]
            lines_colors = ['r', 'g', 'b']
            distance_sum = 0

            for params, line_color in zip(edges_params, lines_colors):
                # 分别画出垂足和垂线
                footpoint = cal_footpoint(params, inner_point)
                plt.plot(*footpoint, 'o', color=line_color)
                pts_data = np.array([inner_point, footpoint])
                plt.plot(pts_data[:, 0],
                         pts_data[:, 1],
                         '--',
                         color=line_color)
                edge_distance = cal_dis2line(params, inner_point)
                distance_sum += edge_distance
                plt.text(np.mean(pts_data[:, 0]),
                         np.mean(pts_data[:, 1]),
                         s=f"{edge_distance:.2f}",
                         color=line_color)

            # 画出内部点和正三角形
            plt.plot(*inner_point, 'o', color='magenta')
            plt.text(*inner_point,
                     s=f"({inner_point[0]:.2f},{inner_point[1]:.2f})",
                     color='magenta')

            plt.plot([-h / 3**0.5, h / 3**0.5, 0, -h / 3**0.5], [0, 0, h, 0],
                     'k')
            plt.axis('equal')
            plt.title(f"Sum of distances to three edges: {distance_sum:.2f}")
            plt.xlim(-h / np.sqrt(3), h / np.sqrt(3))
            plt.ylim(0, h)
            plt.show()

            counter += 1


def display_points_in_equilateral_triangle(
        times: int = 5,
        condition: str = 'no',
        mass: list[float] = [1., 2., 3.]) -> None:
    """显示等边三角形内满足不同条件的点

    Args:
        times (int, optional): 点的数量. Defaults to 5.
        condition (str, optional): 条件类型: `no` , 三角形内; `any` 满足任意一个动量和为0推出的三边关系; `all` 满足所有动量和为0推出的三边关系. Defaults to 'no'. 
        mass (list[float], optional): 三个碎片的质量, 其比值会影响动量和为0推出的三边关系. Defaults to [1.,2.,3.].

    Example:
        >>> display_points_in_equilateral_triangle(1000, 'any', [1,1,1])
        >>> display_points_in_equilateral_triangle(1000, 'all')
        >>> display_points_in_equilateral_triangle(1000, 'all', [2,4,6])
    """
    import matplotlib.markers as mm
    counter = 0
    while (counter < times):
        x0 = (np.random.rand() - 0.5) * 2 * h / np.sqrt(3)
        y0 = np.random.rand()

        # 根据随机点与左右边的关系判断点是否在等边三角形内部
        if (np.sqrt(3) * x0 + y0 - h <= 0) and (np.sqrt(3) * x0 - y0 + h >= 0):
            inner_point = (x0, y0)

            # 计算到三边距离
            d1 = cal_dis2line([0, 1, 0], inner_point) * mass[0]
            d2 = cal_dis2line([np.sqrt(3), 1, -h], inner_point) * mass[1]
            d3 = cal_dis2line([np.sqrt(3), -1, h], inner_point) * mass[2]

            if condition == 'no':
                plt.plot(*inner_point, 'o', color='magenta')
            elif condition == 'any':
                if np.sqrt(d1) <= np.sqrt(d2) + np.sqrt(d3):
                    plt.plot(*inner_point, marker=mm.CARETLEFT, color='r')
                if np.sqrt(d2) <= np.sqrt(d1) + np.sqrt(d3):
                    plt.plot(*inner_point, marker=mm.CARETRIGHT, color='g')
                if np.sqrt(d3) <= np.sqrt(d1) + np.sqrt(d2):
                    plt.plot(*inner_point, marker=mm.CARETUP, color='b')
            elif condition == 'all':
                if np.sqrt(d1) <= np.sqrt(d2) + np.sqrt(d3) and np.sqrt(
                        d2) <= np.sqrt(d1) + np.sqrt(d3) and np.sqrt(
                            d3) <= np.sqrt(d1) + np.sqrt(d2):
                    plt.plot(*inner_point, marker='o', color='b')

            counter += 1

    if condition == 'any':
        plt.title(
            "< means $\sqrt{d_1} \leq \sqrt{d_2} + \sqrt{d_3}$, > means $\sqrt{d_2} \leq \sqrt{d_1} + \sqrt{d_3}$, ^ means $\sqrt{d_3} \leq \sqrt{d_1} + \sqrt{d_2}$"
        )
    elif condition == 'all':
        plt.title(f'$m_1:m_2:m_3 = {mass[0]}:{mass[1]}:{mass[2]}$')
    plt.plot([-h / 3**0.5, h / 3**0.5, 0, -h / 3**0.5], [0, 0, h, 0], 'k')
    plt.axis('equal')
    plt.xlim(-h / np.sqrt(3), h / np.sqrt(3))
    plt.ylim(0, h)
    plt.show()


