class Faker3BodyFragmentation:
    """伪数据生成
    """

    def ekins(num: int = 2000):
        """生成动能伪数据

        Args:
            num (int, optional): 伪数据数量. Defaults to 2000.

        Returns:
            list[list[float]]: 生成的动能伪数据 `[num, 3]` , 每一行为 :math:`[E_1^i, E_2^i, E_3^i]`
        """
        return np.random.rand(num, 3) * 100

    def ekins_line(num: int = 2000) -> list[list[float]]:
        """生成满足如下条件的动能伪数据

        .. math::

            E_1 + E_2 + E_3 = 1

            E_1 = C

        Args:
            num (int, optional): 伪数据数量. Defaults to 2000.

        Returns:
            list[list[float]]: 生成的动能伪数据
        """
        ekins = []
        for _ in range(100):
            E1 = 0.4
            E2E3 = 1 - E1
            E2 = E2E3 * np.random.rand()
            E3 = E2E3 - E2

            ekins.append([E1 + np.random.rand() / 10, E2, E3])

        return np.array(ekins)

    def momentums(num: int = 100):
        """生成动量伪数据, 伪数据满足如下条件

        .. math::

            p_1 + p_{23} = 0

            p_{23} = p_2 + p_1

        Args:
            num (int, optional): 数据数量. Defaults to 100.

        Returns:
            list[list[list[float]]]: 动量伪数据 `[num, 3, 3]`
        """
        # print(Faker3BodyFragmentation.momentums(2))
        ps = np.zeros((num, 3, 3))
        for i in range(num):
            p1 = np.random.rand(3)
            p2p3 = -p1
            p2 = np.random.rand(3)
            p3 = p2p3 - p2
            # p = np.array(Faker3BodyFragmentation.momentums())
            # print(p)
            # print(p.sum(axis=0))
            # print(p[1:].sum(axis=0))
            ps[i] = np.array([p1, p2, p3])
        # return p1, p2, p3
        return ps

    def momentums_circle(num: int = 100):
        """生成满足如下条件的动量伪数据

        .. math::

            p_2 + p_3 &= - p_1

            |p_2|^2 + |p_3|^2 &= 1 = |p_1|^2

        Args:
            num (int, optional): 数据数量. Defaults to 100.

        Returns:
            list[list[list[float]]]: 动量伪数据 `[num, 3, 3]`
        """
        ps = np.zeros((num, 3, 3))
        for i in range(num):
            x2 = -np.random.rand()
            x3 = -1 - x2
            # y2 + y3 = 0
            # x2^2 + x3^2 + y2^2 + y3^2 = 1
            y2 = np.sqrt((1 - x2**2 - x3**2) / 2)
            y3 = -y2

            x2 += (np.random.rand() - 0.5) / 10
            x3 += (np.random.rand() - 0.5) / 10
            y2 += (np.random.rand() - 0.5) / 10
            y2 += (np.random.rand() - 0.5) / 10

            ps[i] = np.array([[1, 0, 0], [x2, y2, 0], [x3, y3, 0]])
        return ps


def ekin2coord(ekins: list[list[float]]) -> tuple[list[float]]:
    """由三体碎裂的动能计算Dalita图坐标, 以底边中点为原点

    Args:
        ekins (list[list[float]]): 未归一化的三体碎裂的动能, 数组形状为 `[num, 3]` , 每一行分别表示 :math:`E_1, E_2, E_3`

    Returns:
        tuple[list[float]]: Dalita图坐标

    Example:
        >>> ekins = np.array([[2,5,3],[4,5,1],[3,4,5]])
        >>> ekin2coord(ekins)
        (array([-0.11547005, -0.23094011,  0.04811252]), array([0.2 , 0.4 , 0.25]))
    """

    ekins_norm = ekins / np.sum(ekins, axis=1, keepdims=True)
    # print(ekins_norm)

    x = (-2 * ekins_norm[:, 1] - ekins_norm[:, 0] + h) / np.sqrt(3)
    y = ekins_norm[:, 0]
    return x, y


def dalitzplot(ekins: list[list[float]] = None, location: str = None) -> None:
    """绘制 Dalitz 图, 以底边中点为原点

    Args:
        ekins (list[list[float]], optional): 未归一化的三体碎裂的动能, 数组形状为 `[num, 3]` , 每一行分别表示 :math:`E_1, E_2, E_3` . Defaults to None.

    Example:
        >>> dalitzplot()

        .. image:: ../../src/img/dalitz_plot_example.png
            :width: 400px
            :align: center
    """
    if ekins is None:
        x, y = ekin2coord(np.random.rand(2000, 3) * 100)
    else:
        x, y = ekin2coord(ekins)

    # 绘制二维散点密度图

    # fig = plt.figure()
    # ax = fig.add_subplot(1, 1, 1, projection='scatter_density')
    # # density = ax.scatter_density(x, y,cmap='rainbow')
    # density = ax.scatter_density(x, y, vmax=vmax, cmap='mycmap')
    # fig.colorbar(density, location)

    # Calculate the point density
    xy = np.vstack([x, y])
    z = gaussian_kde(xy)(xy)

    # Sort the points by density, so that the densest points are plotted last
    idx = z.argsort()
    x, y, z = x[idx], y[idx], z[idx]

    fig, ax = plt.subplots()

    # 绘制等边三角形外框和内切圆
    vertices = [[-h / np.sqrt(3), 0], [h / np.sqrt(3), 0], [0, h]]
    equilateral_triangle = plt.Polygon(xy=vertices, color='k', fill=False)
    ax.add_patch(equilateral_triangle)
    inscribed_circle = plt.Circle(xy=(0, 1 / 3),
                                  radius=1 / 3,
                                  color='k',
                                  fill=False)
    ax.add_patch(inscribed_circle)

    density = ax.scatter(x, y, c=z, s=5, cmap='jet')
    # density = ax.scatter(x, y, c=z, s=5, cmap='jet', norm=LogNorm(vmin=y.min(), vmax=y.max()))
    fig.colorbar(density, shrink=0.9, location=location)

    ax.set_xticks([])
    ax.set_yticks([])
    ax.set_xlim(-h / np.sqrt(3), h / np.sqrt(3))
    ax.set_ylim(0, h)

    ax.axis('off')
    ax.set_aspect('equal')

    plt.tight_layout()
    fig.savefig('dalitz_plot.png')
    plt.show()
    return fig
    


def ekin2coord_rect(ekins: list[list[float]]) -> tuple[list[float]]:
    """由三体碎裂的动能计算Dalita图坐标, 以内接圆圆心为原点

    Args:
        ekins (list[list[float]]): 未归一化的三体碎裂的动能, 数组形状为 `[num, 3]` , 每一行分别表示 :math:`E_1, E_2, E_3`

    Returns:
        tuple[list[float]]: Dalita图坐标
    """
    ekins_sum = np.sum(ekins, axis=1)
    # print(ekins.shape, ekins_sum.shape)

    x = (ekins[:, 0] - ekins[:, 1]) / np.sqrt(3) / ekins_sum
    y = ekins[:, 2] / ekins_sum - 1 / 3
    return x, y


