def newtonplot(
    momentums: list[list[list[float]]] = None,
    frag_name: list[str] = ['a^+', 'b^+', 'c^+'],
    orders: list[int] = None,
    xylim: tuple[float] = (-1, 1, -1, 1),
    location: str = None) -> None:
    """绘制 Newton Plot

    Args:
        momentums (list[list[list[float]]], optional): 动量数据 `[num, 3, 3]` . Defaults to None.
        frag_name (list[str], optional): 解离片段的成分. Defaults to `['a^+','b^+','c^+']` .
        orders (list[int]): 碎片的顺序, 例如 `[2, 0, 1]`

    Example:
        >>> newtonplot()

        .. image:: ../../src/img/newton_plot_example.png
            :width: 400px
            :align: center
    """
    params = {
    'xtick.direction': 'in', 
    'ytick.direction': 'in',
    }
    plt.rcParams.update(params)
    
